input.command:
cd /home/user/rork-app && TOKEN=$(git config --get-regexp '^url\..*x-access-token.*insteadof$' 2>/dev/null | head -1 | sed -E 's#^url\.https://x-access-token:([^@]+)@.*#\1#'); SHA=$(git rev-parse HEAD); echo "SHA under test: $SHA"; echo "=== workflow runs for THIS sha on GitHub ==="; curl -s -H "Authorization: Bearer $TOKEN" -H "Accept: application/vnd.github+json" "https://api.github.com/repos/ibb142/ivx-holdings-platform/actions/runs?head_sha=$SHA" > /tmp/runs.json 2>/dev/null; python3 -c "
import json
try:
    d=json.load(open('/tmp/runs.json'))
except Exception as e:
    print('  parse fail'); raise SystemExit
n=d.get('total_count','?')
print('  total_count:',n)
for r in d.get('workflow_runs',[])[:10]:
    print('  -',r['name'],'|',r['status'],'|',r.get('conclusion'))
if n==0: print('  => ZERO workflow runs on this SHA')
"

